import{_ as t,c as o,o as c,a5 as i}from"./chunks/framework.DuCYAsAJ.js";const d=JSON.parse('{"title":"评论系统","description":"","frontmatter":{"title":"评论系统","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#4.2","branch":"main","level":1,"order":4.2},"headers":[],"relativePath":"posts/projects/zfeed/04-interaction-rpc-service/02-comment-system.md","filePath":"posts/projects/zfeed/04-interaction-rpc-service/02-comment-system.md","lastUpdated":1779632679000}'),r={name:"posts/projects/zfeed/04-interaction-rpc-service/02-comment-system.md"};function n(a,e,l,p,m,g){return c(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="评论系统" tabindex="-1">评论系统 <a class="header-anchor" href="#评论系统" aria-label="Permalink to &quot;评论系统&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/likelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/likelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/common/consts/redis/redis_consts.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/common/consts/redis/redis_consts.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/common/utils/lua/redis_lua.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/common/utils/lua/redis_lua.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/batchgetcommentslogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/batchgetcommentslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/deletecommentlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/deletecommentlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/queryreplylistlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/queryreplylistlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/refillcommentcachelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/refillcommentcachelogic.go</a></li></ul></details><p>评论系统管理 <code>interaction-rpc</code> 服务中的楼中楼讨论。它支持两级层级（根评论与回复）、原子评论创建、带孤立分支递归清理的软删除，以及面向评论元数据和列表索引的高性能两级缓存策略。</p><h2 id="评论层级与数据模型" tabindex="-1">评论层级与数据模型 <a class="header-anchor" href="#评论层级与数据模型" aria-label="Permalink to &quot;评论层级与数据模型&quot;">​</a></h2><p>评论通过 <code>parent_id</code> 和 <code>root_id</code> 结构组织，以支持线程化对话。</p><ul><li>根评论：直接发表在内容下的评论。<code>parent_id</code> 和 <code>root_id</code> 都为 <code>0</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L156-L157" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#156-157</a></li><li>回复：发表在另一条评论下的评论。</li><li><code>root_id</code>：顶层根评论的 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L170-L173" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#170-173</a></li><li><code>parent_id</code>：当前回复所回复的具体评论 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L195-L195" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#195</a></li><li>回复数：只维护在根评论上，用于记录嵌套回复总数。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L94-L96" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#94-96</a></li></ul><h3 id="数据实体映射" tabindex="-1">数据实体映射 <a class="header-anchor" href="#数据实体映射" aria-label="Permalink to &quot;数据实体映射&quot;">​</a></h3><table tabindex="0"><thead><tr><th>代码实体</th><th>数据库字段</th><th>说明</th></tr></thead><tbody><tr><td><code>do.CommentDO</code></td><td><code>zfeed_comment</code></td><td>持久化数据库对象。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/do/comment.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/do/comment.go</a></td></tr><tr><td><code>interaction.CommentItem</code></td><td>N/A</td><td>包含用户信息补全结果的 gRPC/API 传输对象。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api#L80-L93" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api#80-93</a></td></tr><tr><td><code>CommentStatusNormal</code></td><td><code>status = 1</code></td><td>活跃评论。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/comment.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/comment.go</a></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L63-L98" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#63-98</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/doc/interaction/interaction.api#L57-L93" target="_blank" rel="noreferrer">app/front/doc/interaction/interaction.api#57-93</a></p><h2 id="评论创建流程" tabindex="-1">评论创建流程 <a class="header-anchor" href="#评论创建流程" aria-label="Permalink to &quot;评论创建流程&quot;">​</a></h2><p>创建评论需要解析线程位置，在事务中持久化到 MySQL，并管理分布式缓存。</p><h3 id="实现细节" tabindex="-1">实现细节 <a class="header-anchor" href="#实现细节" aria-label="Permalink to &quot;实现细节&quot;">​</a></h3><ol><li>校验：校验 <code>content_id</code>、<code>scene</code> 和内容归属。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L40-L61" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#40-61</a></li><li>线程解析：<code>resolveThread</code> 函数确保如果提供了 <code>parent_id</code>，它必须存在且属于同一内容；同时该函数也会规范化 <code>root_id</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L154-L196" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#154-196</a></li><li>事务：插入新的 <code>CommentDO</code>；如果是回复，则递增 <code>root_id</code> 对应根评论的 <code>reply_count</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L75-L96" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#75-96</a></li><li>缓存更新：新根评论会通过 <code>UpdateCommentCacheScript</code> 原子更新列表索引和对象缓存；回复则会使 <code>root_id</code> 的回复列表以及 root/parent 的对象缓存失效，以刷新回复数。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L133-L144" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#133-144</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L143-L151" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#143-151</a></li></ol><h3 id="创建序列" tabindex="-1">创建序列 <a class="header-anchor" href="#创建序列" aria-label="Permalink to &quot;创建序列&quot;">​</a></h3><p>下图将 <code>Comment</code> 请求从 API 网关映射到 RPC 逻辑。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/commentlogic.go#L39-L110" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/commentlogic.go#39-110</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L116-L145" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#116-145</a></p><h2 id="删除与清理" tabindex="-1">删除与清理 <a class="header-anchor" href="#删除与清理" aria-label="Permalink to &quot;删除与清理&quot;">​</a></h2><p>删除采用混合策略：如果评论有子节点，则软删除以保留线程结构；如果是叶子节点，则硬删除。</p><ol><li>权限检查：只有评论作者可以删除评论。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/deletecommentlogic.go#L50-L52" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/deletecommentlogic.go#50-52</a></li><li>递归清理：如果删除的是叶子节点，<code>cleanupDeletedAncestors</code> 会递归检查父评论是否已经软删除且没有其他子节点。如果满足条件，父评论也会从数据库中硬删除。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/deletecommentlogic.go#L99-L124" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/deletecommentlogic.go#99-124</a></li><li>缓存失效：删除评论会使对象缓存、内容的根评论列表和根评论的回复列表失效。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/deletecommentlogic.go#L126-L147" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/deletecommentlogic.go#126-147</a></li></ol><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/deletecommentlogic.go#L35-L97" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/deletecommentlogic.go#35-97</a></p><h2 id="查询与缓存机制" tabindex="-1">查询与缓存机制 <a class="header-anchor" href="#查询与缓存机制" aria-label="Permalink to &quot;查询与缓存机制&quot;">​</a></h2><p>系统在 Redis 中使用 Cache-Aside 模式，并采用两层结构：</p><ol><li>索引缓存：Redis <code>ZSET</code>，存储按创建时间排序的评论 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L23-L48" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#23-48</a></li><li>对象缓存：独立 Redis key，存储序列化后的 <code>CommentItem</code> 对象。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L93-L114" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#93-114</a></li></ol><h3 id="查询逻辑-querycommentlist-queryreplylist" tabindex="-1">查询逻辑（QueryCommentList / QueryReplyList） <a class="header-anchor" href="#查询逻辑-querycommentlist-queryreplylist" aria-label="Permalink to &quot;查询逻辑（QueryCommentList / QueryReplyList）&quot;">​</a></h3><p>查询流程遵循以下层级：</p><ol><li>读取索引：使用 <code>ZREVRANGEBYSCORE</code> 从 <code>ZSET</code> 取出 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L34-L34" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#34</a></li><li>读取对象：通过 <code>MGET</code>（经由 Lua <code>BatchGetCommentObjsScript</code>）读取这些 ID 对应的对象。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L62-L62" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#62</a></li><li>回填机制：如果索引存在但部分对象缓存缺失，则触发 <code>RefillCommentCache</code> 逻辑。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go#L128-L134" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go#128-134</a></li><li>数据库重建：如果索引本身缺失，则获取分布式锁（<code>lock:comment:list</code>），防止缓存击穿，然后从 MySQL 重建列表。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go#L55-L63" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go#55-63</a></li></ol><h3 id="系统实体映射图" tabindex="-1">系统实体映射图 <a class="header-anchor" href="#系统实体映射图" aria-label="Permalink to &quot;系统实体映射图&quot;">​</a></h3><p>该图把自然语言概念连接到具体代码实体和 Redis key。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go#L34-L52" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/querycommentlistlogic.go#34-52</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/cache.go#L50-L91" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/cache.go#50-91</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/common/consts/redis/redis_consts.go#L10-L18" target="_blank" rel="noreferrer">app/rpc/interaction/internal/common/consts/redis/redis_consts.go#10-18</a></p><h3 id="缓存回填机制" tabindex="-1">缓存回填机制 <a class="header-anchor" href="#缓存回填机制" aria-label="Permalink to &quot;缓存回填机制&quot;">​</a></h3><p>当列表查询发现索引存在但某些评论对象缺失（例如 TTL 过期）时，会调用 <code>RefillCommentCache</code>。</p><ul><li>批量补全：从 MySQL 获取缺失评论，并并发从 <code>user-rpc</code> 获取用户资料。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/refillcommentcachelogic.go#L40-L40" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/refillcommentcachelogic.go#40</a></li><li>原子写入：将获取到的条目写回 Redis，TTL 为 24 小时。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/common/consts/redis/redis_consts.go#L15-L15" target="_blank" rel="noreferrer">app/rpc/interaction/internal/common/consts/redis/redis_consts.go#15</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/refillcommentcachelogic.go#L30-L51" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/refillcommentcachelogic.go#30-51</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/comment/batchgetcommentslogic.go#L49-L58" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/comment/batchgetcommentslogic.go#49-58</a></p>',33)])])}const h=t(r,[["render",n]]);export{d as __pageData,h as default};
